import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { authService } from "@/services/authService";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Loader2 } from "lucide-react";
import { ErrorAlert } from "@/components/ErrorAlert";

// ─── Specific auth error message mapping ──────────────────────────────────────
function mapAuthError(rawMessage: string, mode: "signin" | "signup"): { title: string; message: string } {
  const msg = rawMessage.toLowerCase();

  // Signup: email already exists
  if (mode === "signup" && (msg.includes("already") || msg.includes("registered") || msg.includes("exists") || msg.includes("duplicate") || msg.includes("unique"))) {
    return { title: "Email Sudah Digunakan", message: "Email sudah terdaftar. Silakan gunakan email lain atau login." };
  }

  // Login: user not found
  if (mode === "signin" && (msg.includes("not found") || msg.includes("no user") || msg.includes("invalid login") || msg.includes("user does not exist"))) {
    return { title: "Akun Tidak Ditemukan", message: "Akun tidak ditemukan. Silakan Signup terlebih dahulu." };
  }

  // Wrong password
  if (msg.includes("password") || msg.includes("credentials") || msg.includes("invalid") || msg.includes("incorrect")) {
    return { title: "Password Salah", message: "Password salah. Silakan coba lagi." };
  }

  // Server error
  if (msg.includes("500") || msg.includes("503") || msg.includes("server") || msg.includes("unavailable")) {
    return { title: "Server Bermasalah", message: "Server sedang bermasalah, silakan coba beberapa saat lagi." };
  }

  // Fallback
  return {
    title: mode === "signin" ? "Sign In Gagal" : "Sign Up Gagal",
    message: rawMessage || "Terjadi kesalahan. Silakan coba lagi.",
  };
}

interface AuthScreenProps {
  onAuthenticated?: () => void;
}

export const AuthScreen = ({ onAuthenticated }: AuthScreenProps) => {
  const [mode, setMode] = useState<"signin" | "signup">("signin");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [username, setUsername] = useState("");
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  const [visible, setVisible] = useState(false);
  const [isExiting, setIsExiting] = useState(false);

  // Global error state for inline alert box
  const [errorTitle, setErrorTitle] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const showError = (title: string, message: string, status?: number, rawMsg?: string) => {
    setErrorTitle(title);
    setErrorMessage(message);
    console.error(`[ERROR_LOG] Status: ${status ?? "unknown"} | Message: ${rawMsg ?? message}`);
  };

  const clearError = () => { setErrorTitle(null); setErrorMessage(null); };

  useEffect(() => { setVisible(true); }, []);

  // Clear error when switching mode
  useEffect(() => { clearError(); }, [mode]);

  const validateForm = () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      showError("Format Email Salah", "Masukkan alamat email yang valid.", 0);
      return false;
    }
    if (password.length < 6) {
      showError("Password Terlalu Pendek", "Password harus minimal 6 karakter.", 0);
      return false;
    }
    if (mode === "signup" && !username.trim()) {
      showError("Username Wajib", "Masukkan username untuk akunmu.", 0);
      return false;
    }
    return true;
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    clearError();
    if (!validateForm()) return;

    setLoading(true);

    try {
      const { error } =
        mode === "signin"
          ? await authService.login(email, password)
          : await authService.signup(email, password, username);

      if (error) {
        setLoading(false);
        const raw = error.message || "";
        const mapped = mapAuthError(raw, mode);
        showError(mapped.title, mapped.message, undefined, raw);
        return;
      }

      // Success
      setLoading(false);
      setIsExiting(true);
      setTimeout(() => {
        onAuthenticated?.();
        window.location.reload();
      }, 800);

    } catch (err: any) {
      setLoading(false);
      const raw = err?.message || String(err);
      const mapped = mapAuthError(raw, mode);
      showError(mapped.title, mapped.message, err?.status, raw);
    }
  };

  const handleGoogleLogin = async () => {
    clearError();
    setGoogleLoading(true);
    const { error } = await authService.loginWithGoogle();
    if (error) {
      setGoogleLoading(false);
      showError("Google Sign In Gagal", error.message || "Tidak bisa menghubungkan ke Google. Coba lagi.");
    }
    // If no error, browser redirects to Google — no need to reset loading
  };

  const toggleMode = () => {
    if (loading) return;
    setMode(mode === "signin" ? "signup" : "signin");
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto overflow-x-hidden bg-background/80 backdrop-blur-sm">
      <div className="min-h-full w-full flex flex-col items-center justify-center py-6 sm:py-12 relative">
        {/* Background blobs */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
          <div className="absolute top-[-20%] left-[-10%] w-[500px] h-[500px] bg-primary/20 rounded-full blur-[100px] animate-pulse-slow" />
          <div className="absolute bottom-[-20%] right-[-10%] w-[500px] h-[500px] bg-purple-500/20 rounded-full blur-[100px] animate-pulse-slow" />
        </div>

        {/* ── Global Error Alert — top center ── */}
        <ErrorAlert message={errorMessage} title={errorTitle ?? undefined} onClose={clearError} />

        <div
          className={`relative z-10 w-full max-w-md mx-4 transition-all duration-500 ease-out transform ${visible && !isExiting ? "opacity-100 scale-100 translate-y-0" : "opacity-0 scale-95 translate-y-4"
            }`}
        >
        <div className="bg-card/50 backdrop-blur-xl border border-border/50 shadow-2xl rounded-2xl overflow-hidden">
          {/* Header */}
          <div className="p-6 sm:p-8 text-center bg-gradient-to-b from-primary/5 to-transparent">
            <div className="w-16 h-16 sm:w-20 sm:h-20 bg-background rounded-2xl shadow-lg mx-auto mb-4 sm:mb-6 flex items-center justify-center transform transition-transform hover:rotate-12 duration-500">
              <img src="/AicodeLogo.png" alt="AIcode Logo" className="w-12 h-12 sm:w-16 sm:h-16 dark-invert" draggable={false} />
            </div>
            <h2 className="text-2xl sm:text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-primary to-purple-600 mb-1 sm:mb-2 text-balance leading-tight">
              {mode === "signin" ? "Welcome Back" : "Create Account"}
            </h2>
            <p className="text-muted-foreground text-[13px] sm:text-sm px-2">
              {mode === "signin"
                ? "Enter your credentials to access your workspace"
                : "Join us and start your AI coding journey"}
            </p>
          </div>

          {/* Form */}
          <div className="p-6 sm:p-8 pt-0">
            <form onSubmit={handleAuth} className="space-y-4 sm:space-y-5">
              <div className="space-y-4">
                {/* Email */}
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email" type="email" placeholder="name@example.com"
                    value={email} onChange={(e) => setEmail(e.target.value)}
                    className="bg-background/50 border-border/50 focus:border-primary focus:ring-primary/20 transition-all text-base sm:text-sm"
                    required disabled={loading}
                  />
                </div>

                {/* Username (signup only) */}
                {mode === "signup" && (
                  <div className="space-y-2 animate-in slide-in-from-left-4 fade-in duration-500">
                    <Label htmlFor="username">Username</Label>
                    <Input
                      id="username" type="text" placeholder="Display Name"
                      value={username} onChange={(e) => setUsername(e.target.value)}
                      className="bg-background/50 border-border/50 focus:border-primary focus:ring-primary/20 transition-all text-base sm:text-sm"
                      required disabled={loading}
                    />
                  </div>
                )}

                {/* Password */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="password">Password</Label>
                    {mode === "signin" && (
                      <Link
                        to="/forgot-password"
                        className="text-xs text-muted-foreground hover:text-primary transition-colors"
                        tabIndex={loading ? -1 : undefined}
                      >
                        Lupa Password?
                      </Link>
                    )}
                  </div>
                  <Input
                    id="password" type="password" placeholder="••••••••"
                    value={password} onChange={(e) => setPassword(e.target.value)}
                    className="bg-background/50 border-border/50 focus:border-primary focus:ring-primary/20 transition-all text-base sm:text-sm"
                    required disabled={loading}
                  />
                </div>
              </div>

              <Button
                type="submit" disabled={loading}
                className="w-full h-10 sm:h-11 text-base sm:text-lg font-medium shadow-lg shadow-primary/25 hover:shadow-primary/40 transition-all"
              >
                {loading ? (
                  <Loader2 className="w-5 h-5 animate-spin mr-2" />
                ) : (
                  mode === "signin" ? "Sign In" : "Create Account"
                )}
              </Button>

              {/* Toggle Mode */}
              <div className="text-center text-sm text-muted-foreground mt-4">
                {mode === "signin" ? (
                  <>
                    Belum punya akun?{' '}
                    <button
                      type="button"
                      onClick={toggleMode}
                      className="text-primary hover:underline font-medium transition-colors"
                      disabled={loading}
                    >
                      Daftar sekarang
                    </button>
                  </>
                ) : (
                  <>
                    Sudah punya akun?{' '}
                    <button
                      type="button"
                      onClick={toggleMode}
                      className="text-primary hover:underline font-medium transition-colors"
                      disabled={loading}
                    >
                      Sign in
                    </button>
                  </>
                )}
              </div>
            </form>

            {/* OR Divider */}
            <div className="mt-5 flex items-center gap-3">
              <div className="flex-1 h-px bg-border/50" />
              <span className="text-xs text-muted-foreground font-medium tracking-widest uppercase">or</span>
              <div className="flex-1 h-px bg-border/50" />
            </div>

            {/* Google Sign In Button */}
            <Button
              type="button"
              variant="outline"
              disabled={googleLoading || loading}
              onClick={handleGoogleLogin}
              className="w-full h-10 sm:h-11 mt-3 sm:mt-4 text-sm sm:text-base font-medium border-border/50 bg-background/50 hover:bg-background/80 transition-all flex items-center justify-center gap-2 sm:gap-3"
            >
              {googleLoading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <svg className="w-4 h-4" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                  <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                  <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                  <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                </svg>
              )}
              {googleLoading ? "Redirecting to Google..." : "Continue with Google"}
            </Button>

            <div className="mt-8 pt-4 border-t border-border/30 text-center space-y-2">
              <p className="text-[10px] text-muted-foreground leading-relaxed">
                Dengan melanjutkan, Anda menyetujui <a href="https://unklab-aicode.online/terms" className="text-primary hover:underline">Syarat & Ketentuan</a> dan <a href="https://unklab-aicode.online/privacy" className="text-primary hover:underline">Kebijakan Privasi</a> kami.
              </p>
            </div>
          </div>
        </div>
      </div>
      </div>
    </div>
  );
};

import { useState, useRef, useEffect, forwardRef, useImperativeHandle } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Send, Loader2, Plus, X, PanelLeft, LogIn, MessageSquare, AlertCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { authService } from "@/services/authService";
import { useAuth } from "@/context/AuthContext";
import { backendService } from "@/services/backendService";
import { fetchUserApiKey, streamGeminiResponse, clearCachedApiKey } from "@/services/geminiService";
import { streamGroqFallback } from "@/services/groqFallbackService";
import { ChatSidebar } from "./ChatSidebar";
import { AIStatusIndicator } from "./AIStatusIndicator";
import { ErrorAlert } from "./ErrorAlert";
import { ChatMessageBubble } from "./chat/ChatMessageBubble";
import { buildContext, type CellSnapshot } from "@/utils/notebookContext";
import { containsProfanity } from "@/utils/profanityFilter";
import { ChatInputForm } from "./chat/ChatInputForm";

// ─── Chat-specific error mapping ─────────────────────────────────────────────
function mapChatError(err: any): { title: string; message: string; status: number | string } {
  const raw: string = err?.message || String(err) || "";
  const lower = raw.toLowerCase();

  // 429 — quota / rate limit
  if (raw.includes("429") || lower.includes("quota") || lower.includes("rate limit") || lower.includes("too many")) {
    return { title: "Kuota AI Habis", message: "Kuota harian AI habis. Silakan coba lagi nanti atau ganti API key.", status: 429 };
  }

  // Network / offline
  if (lower.includes("fetch") || lower.includes("network") || lower.includes("failed to fetch") || lower.includes("networkerror") || !navigator.onLine) {
    return { title: "Koneksi Terputus", message: "Koneksi internet terganggu, gagal mengirim pesan. Periksa koneksimu dan coba lagi.", status: 0 };
  }

  // API key missing/invalid
  if (lower.includes("api key") || lower.includes("api_key") || lower.includes("invalid key") || lower.includes("unauthorized")) {
    return { title: "API Key Tidak Valid", message: "API key tidak valid atau sudah kedaluwarsa. Perbarui di menu Settings.", status: 401 };
  }

  // Server error
  if (raw.includes("500") || raw.includes("503") || lower.includes("server")) {
    return { title: "Server Bermasalah", message: "Server AI sedang bermasalah, silakan coba beberapa saat lagi.", status: 500 };
  }

  return { title: "Gagal Mengirim", message: raw || "Terjadi kesalahan. Silakan coba lagi.", status: "unknown" };
}

interface Message {
  role: "user" | "assistant";
  content: string;
  /** Token usage info — hanya ada di pesan assistant dari Gemini */
  inputTokens?: number;
  outputTokens?: number;
  /** Aktifkan typewriter animation saat pesan pertama kali ditambahkan */
  animateOnAdd?: boolean;
}

export type ChatInterfaceHandle = {
  sendMessage: (content: string) => void;
  /** Tampilkan pesan langsung sebagai balasan AI — dengan typewriter animation & token info */
  displayAssistantMessage: (content: string, usage?: { inputTokens: number; outputTokens: number }) => void;
  getConversationId: () => string | null;
  /** Membuat chat baru (jika belum ada) dan update state chatnya, mereturn conversationId */
  getOrCreateConversationId: (title: string) => Promise<string | null>;
  getCurrentUserId: () => string | null;
};

type ChatProps = {
  getCurrentCode?: () => string;
  getNotebookContext?: () => CellSnapshot[] | undefined;
  onLoadCode?: (code: string) => void;
  onSignInClick?: () => void;
  isChallengeActive?: boolean;
  onRemoveChallenge?: () => void;
};

export const ChatInterface = forwardRef<ChatInterfaceHandle, ChatProps>((props, ref) => {
  const { user: authUser, isLoading: authLoading } = useAuth();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();

  const [conversationId, setConversationId] = useState<string | null>(null);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [conversations, setConversations] = useState<Array<{ id: string; title: string; created_at: string; last_code?: string | null }>>([]);
  const [showNewModal, setShowNewModal] = useState(false);
  const [newChatTitle, setNewChatTitle] = useState("New Chat");
  const [currentTitle, setCurrentTitle] = useState<string>("");
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [aiStage, setAiStage] = useState<'idle' | 'thinking' | 'verifying' | 'done'>('idle');
  const [noApiKey, setNoApiKey] = useState(false);
  // true while Groq fallback is actively streaming
  const [usingFallback, setUsingFallback] = useState(false);

  // Global chat error state (shown in ErrorAlert)
  const [chatError, setChatError] = useState<{ title: string; message: string } | null>(null);

  // Hint terakhir dari cek jawaban (ditampilkan di lock screen saat challenge aktif)
  const [lastChallengeHint, setLastChallengeHint] = useState<string | null>(null);

  // Ref to avoid stale closure in useImperativeHandle
  const isLoadingRef = useRef(false);

  const showChatError = (err: any) => {
    const mapped = mapChatError(err);
    setChatError({ title: mapped.title, message: mapped.message });
    console.error(`[ERROR_LOG] Status: ${mapped.status} | Message: ${err?.message ?? mapped.message}`);
  };

  const abortControllerRef = useRef<AbortController | null>(null);

  // ── Scroll to bottom on new messages ──────────────────────────────────────
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // ── Init: load user + conversations ───────────────────────────────────────
  // Wait until AuthContext has finished checking the cookie session (isLoading=false)
  // before attempting to fetch data. This prevents the /conversations/undefined bug.
  useEffect(() => {
    if (authLoading) return; // Wait for auth check to complete first

    const init = async () => {
      const user = authUser; // Use user from AuthContext (already hydrated)
      if (!user) return;
      const userId = user.id;
      setCurrentUserId(userId);
      setLoadingHistory(true);

      const { data: convList } = await backendService.getConversations(userId, 50);
      setConversations(convList || []);

      if (convList && convList.length > 0) {
        const latest = convList[0];
        setCurrentTitle(latest.title || "Untitled");
        setConversationId(latest.id);

        const { data: msgs } = await backendService.getMessages(latest.id);
        if (msgs) setMessages(msgs.map((m) => ({ role: m.role, content: m.content })));

        const { data: snippets } = await backendService.getCodeByConversation(latest.id);
        const code = snippets?.[0]?.code_content ?? latest.last_code ?? null;
        if (code) {
          if (props.onLoadCode) props.onLoadCode(code);
        }
      }
      setLoadingHistory(false);
    };
    init();

    return () => { abortControllerRef.current?.abort(); };
  }, [authLoading, authUser]);

  // ── Reset hint saat tantangan selesai ─────────────────────────────────────
  useEffect(() => {
    if (!props.isChallengeActive) {
      setLastChallengeHint(null);
    }
  }, [props.isChallengeActive]);

  // ── Sliding Window — batasi history yang dikirim ke AI ─────────────────────
  // History lengkap tetap tampil di UI & tersimpan di DB.
  // Hanya N pesan terakhir yang dikirim ke Gemini/Groq agar hemat token.
  const CHAT_WINDOW_SIZE = 10; // 5 pasang tanya-jawab

  // ── Core chat function — calls Gemini (with 30s timeout) → Groq fallback ────
  // `allMessages` = the complete conversation to send (including the new user msg)
  const chatOnce = async (allMessages: Message[]) => {
    if (isLoadingRef.current) return;
    isLoadingRef.current = true;
    setIsLoading(true);
    setNoApiKey(false);
    setUsingFallback(false);

    if (abortControllerRef.current) abortControllerRef.current.abort();
    abortControllerRef.current = new AbortController();
    const mainSignal = abortControllerRef.current.signal;

    try {
      const user = authService.getUser();
      if (!user) {
        toast({ title: "Not logged in", description: "Please sign in to chat" });
        return;
      }

      const userId = user.id;

      // ── 1. Get API key (cached after first fetch) ────────────────────────
      let apiKey: string;
      try {
        apiKey = await fetchUserApiKey(userId); // cookie handles auth
      } catch (keyErr: any) {
        setNoApiKey(true);
        toast({ title: "API Key Missing", description: keyErr.message, variant: "destructive" });
        return;
      }

      // ── 2. Ensure conversation exists ────────────────────────────────────
      let convId = conversationId;
      if (!convId) {
        const { data: conv, error: convErr } = await backendService.createConversation(userId, "New Chat");
        if (convErr) throw convErr;
        convId = conv!.id;
        setConversationId(convId);
        setCurrentTitle("New Chat");
        const { data: convList } = await backendService.getConversations(userId, 50);
        setConversations(convList || []);
      }

      // ── 3. Save user message to DB (fire-and-forget) ────────────────────
      const lastUserMsg = allMessages[allMessages.length - 1];
      backendService.addMessage(convId, userId, "user", lastUserMsg.content).catch(console.warn);

      if (containsProfanity(lastUserMsg.content)) {
        const reply = "Kalau lagi marah jangan coding dulu ya 😊 Santai tarik napas dulu...";
        
        setMessages((prev) => [...prev, {
          role: "assistant", 
          content: reply, 
          animateOnAdd: true 
        }]);
        
        backendService.addMessage(convId, userId, "assistant", reply).catch(console.warn);
        
        setIsLoading(false);
        isLoadingRef.current = false;
        setAiStage('idle');
        abortControllerRef.current = null;
        return;
      }

      // ── 4. Show thinking indicator ───────────────────────────────────────
      setAiStage('thinking');
      const thinkTimer = setTimeout(() => setAiStage('verifying'), 1200);

      // ── 5. Add streaming placeholder ─────────────────────────────────────
      setMessages((prev) => [...prev, { role: "assistant", content: "" }]);

      // ── 6. Shared streaming state ────────────────────────────────────────
      let isFirstChunk = true;
      let fullText = "";
      let msgInputTokens = 0;
      let msgOutputTokens = 0;

      // Chunk handler — dipakai oleh Gemini DAN Groq
      const handleChunk = (chunk: string) => {
        if (isFirstChunk) {
          isFirstChunk = false;
          clearTimeout(thinkTimer);
          setAiStage('done');
          setTimeout(() => setAiStage('idle'), 800);
        }
        fullText += chunk;
        setMessages((prev) => {
          const updated = [...prev];
          const idx = updated.length - 1;
          if (updated[idx]?.role === 'assistant') {
            updated[idx] = { role: "assistant", content: fullText };
          }
          return updated;
        });
      };

      // ── 7. Sliding window — ambil N pesan terakhir saja untuk dikirim ke AI ─
      // allMessages masih lengkap untuk disimpan di DB (step 3 di atas).
      let windowedMessages = allMessages.length > CHAT_WINDOW_SIZE
        ? allMessages.slice(-CHAT_WINDOW_SIZE)
        : [...allMessages];

      // ── 7.5. Inject Notebook Context ─────────────────────────────────────────
      // Inject context HANYA pada pesan terakhir yang akan dikirim ke API
      // (UI/State 'allMessages' tidak terpengaruh, jadi chat UI tetap bersih)
      if (props.getNotebookContext) {
        const cells = props.getNotebookContext();
        if (cells) {
          const lastMsg = windowedMessages[windowedMessages.length - 1];
          const injectedContext = buildContext(lastMsg.content, cells);
          if (injectedContext) {
            windowedMessages[windowedMessages.length - 1] = {
              ...lastMsg,
              content: lastMsg.content + injectedContext,
            };
          }
        }
      }

      // ── 8. Gemini stream + 30-detik timeout ──────────────────────────────────
      // AbortController khusus untuk Gemini (agar bisa di-abort tanpa
      // membatalkan seluruh chatOnce — Groq masih bisa berjalan setelahnya)
      const geminiAbort = new AbortController();
      // Kalau user cancel (mainSignal), abort Gemini juga
      mainSignal.addEventListener('abort', () => geminiAbort.abort(), { once: true });

      let timedOut = false;
      let timeoutHandle: ReturnType<typeof setTimeout>;

      // Promise yang reject setelah 30 detik
      const timeoutPromise = new Promise<never>((_, reject) => {
        timeoutHandle = setTimeout(() => {
          timedOut = true;
          geminiAbort.abort('GEMINI_TIMEOUT'); // stop streaming → hemat token Gemini
          reject(new Error('GEMINI_TIMEOUT'));
        }, 30_000);
      });

      try {
        // Race: siapa yang selesai duluan — Gemini atau timeout?
        const geminiResult = await Promise.race([
          streamGeminiResponse(apiKey, windowedMessages, handleChunk, geminiAbort.signal),
          timeoutPromise,
        ]);
        clearTimeout(timeoutHandle!);
        // Tangkap token usage dari Gemini
        msgInputTokens = geminiResult.usage.inputTokens;
        msgOutputTokens = geminiResult.usage.outputTokens;

      } catch (geminiErr: any) {
        clearTimeout(timeoutHandle!);

        if (timedOut && !mainSignal.aborted) {
          // ── 8. FALLBACK: Gemini timeout → switch ke Groq ───────────────
          // Reset state streaming agar Groq mulai dari awal (bersih)
          isFirstChunk = true;
          fullText = "";
          setAiStage('thinking');
          setMessages((prev) => {
            const updated = [...prev];
            const last = updated[updated.length - 1];
            if (last?.role === 'assistant') {
              updated[updated.length - 1] = { role: 'assistant', content: '' };
            }
            return updated;
          });

          toast({
            title: "⚡ Backup AI Aktif",
            description: "Gemini lambat (>30 detik), beralih ke Kimi K2 (Groq)...",
            duration: 4000,
          });

          setUsingFallback(true);
          try {
            await streamGroqFallback(windowedMessages, handleChunk, mainSignal);
          } finally {
            setUsingFallback(false);
          }

        } else if (!mainSignal.aborted) {
          // Error Gemini bukan timeout dan bukan user cancel → lempar
          throw geminiErr;
        }
      }

      // Kalau stream sama sekali tidak menghasilkan chunk
      if (isFirstChunk) {
        clearTimeout(thinkTimer);
        setAiStage('idle');
      }

      // ── 9. Simpan balasan AI ke DB + update pesan dengan token info ────────
      if (fullText && convId) {
        backendService.addMessage(convId, userId, "assistant", fullText).catch(console.warn);
      }
      // Update pesan terakhir (assistant) dengan token usage
      if (msgInputTokens > 0 || msgOutputTokens > 0) {
        setMessages((prev) => {
          const updated = [...prev];
          const last = updated[updated.length - 1];
          if (last?.role === 'assistant') {
            updated[updated.length - 1] = {
              ...last,
              inputTokens: msgInputTokens,
              outputTokens: msgOutputTokens,
            };
          }
          return updated;
        });
      }

    } catch (error: any) {
      setAiStage('idle');
      if (error?.name !== 'AbortError') {
        showChatError(error);
        // Hapus placeholder kosong
        setMessages((prev) => {
          const last = prev[prev.length - 1];
          if (last?.role === 'assistant' && !last.content) return prev.slice(0, -1);
          return prev;
        });
      }
    } finally {
      isLoadingRef.current = false;
      setIsLoading(false);
      abortControllerRef.current = null;
    }
  };

  // ── Send handler ───────────────────────────────────────────────────────────
  const handleSend = async (content: string) => {
    if (!content.trim() || isLoadingRef.current) return;
    setMessages((prev) => {
      const next = [...prev, { role: "user" as const, content }];
      // Using setTimeout(0) to call chatOnce outside the render cycle
      setTimeout(() => chatOnce(next), 0);
      return next;
    });
  };

  useImperativeHandle(ref, () => ({
    sendMessage: (content: string) => {
      if (isLoadingRef.current) return;
      setMessages((prev) => {
        const next = [...prev, { role: "user" as const, content }];
        setTimeout(() => chatOnce(next), 0);
        return next;
      });
    },
    displayAssistantMessage: (content: string, usage?: { inputTokens: number; outputTokens: number }) => {
      // Tampilkan langsung sebagai pesan AI dengan typewriter animation
      setMessages((prev) => [...prev, {
        role: "assistant" as const,
        content,
        animateOnAdd: true,
        inputTokens: usage?.inputTokens,
        outputTokens: usage?.outputTokens,
      }]);
      // Jika challenge masih aktif, simpan sebagai hint untuk ditampilkan di lock screen
      setLastChallengeHint(content);
      // Simpan ke DB jika ada conversation aktif
      if (conversationId && currentUserId) {
        backendService.addMessage(conversationId, currentUserId, "assistant", content).catch(console.warn);
      }
    },
    getConversationId: () => conversationId,
    getOrCreateConversationId: async (title: string) => {
      if (conversationId) return conversationId;
      if (!currentUserId) return null;
      try {
        const { data: newConv } = await backendService.createConversation(currentUserId, title);
        if (newConv) {
          setConversationId(newConv.id);
          setCurrentTitle(newConv.title);
          const { data: convList } = await backendService.getConversations(currentUserId, 50);
          setConversations(convList || []);
          return newConv.id;
        }
      } catch (err) {
        console.error("Gagal buat auto-conversation", err);
      }
      return null;
    },
    getCurrentUserId: () => currentUserId,
  }));

  // ── Conversation switching ─────────────────────────────────────────────────
  const handleSwitchConversation = async (id: string) => {
    if (id === conversationId) {
      setShowHistory(false);
      return;
    }

    const user = authService.getUser();
    if (!user) return;
    const userId = user.id;

    // 1. Auto-save current code (FIRE AND FORGET — don't block UI)
    if (conversationId && props.getCurrentCode) {
      const code = props.getCurrentCode();
      if (code?.trim()) {
        backendService.saveCodeSnippet(userId, code, "python", conversationId, `Auto-save ${new Date().toLocaleTimeString()}`).catch(console.warn);
      }
    }

    // 2. Clear UI instantly for snappy feel
    setConversationId(id);
    const c = conversations.find(x => x.id === id);
    if (c) setCurrentTitle(c.title);
    setMessages([]);
    setShowHistory(false);
    setLoadingHistory(true);

    // 3. Fetch all required data CONCURRENTLY (Parallel)
    const [msgsRes, snippetsRes, convRes] = await Promise.all([
      backendService.getMessages(id),
      backendService.getCodeByConversation(id),
      backendService.getConversation(id),
    ]);

    setMessages((msgsRes.data || []).map((m) => ({ role: m.role, content: m.content })));

    let restoredCode: string | null = snippetsRes.data?.[0]?.code_content ?? null;
    if (!restoredCode) restoredCode = convRes.data?.last_code ?? null;

    if (restoredCode && props.onLoadCode) {
      props.onLoadCode(restoredCode);
      toast({ title: "Code Restored", description: `Loaded code for "${c?.title || 'this chat'}"`, duration: 1500 });
    } else if (props.onLoadCode) {
      // Clear code if completely empty
      props.onLoadCode("");
    }

    setLoadingHistory(false);
  };

  // ── Rename conversation ────────────────────────────────────────────────────
  const handleRenameConversation = async (id: string, newTitle: string) => {
    // Optimistic update — update UI immediately
    setConversations((prev) =>
      prev.map((c) => (c.id === id ? { ...c, title: newTitle } : c))
    );
    if (conversationId === id) setCurrentTitle(newTitle);

    const { error } = await backendService.updateConversation(id, { title: newTitle });
    if (error) {
      // Revert on failure by re-fetching
      if (currentUserId) {
        const { data: convList } = await backendService.getConversations(currentUserId, 50);
        setConversations(convList || []);
      }
      toast({ title: "Gagal Mengubah Nama", description: "Nama percakapan tidak bisa disimpan. Coba lagi.", variant: "destructive" });
    }
  };

  // ── Unauthenticated state ──────────────────────────────────────────────────
  if (!authService.isAuthenticated()) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-6 h-full">
        <Card className="w-full max-w-sm border-dashed border-2">
          <CardHeader className="text-center pb-2">
            <div className="mx-auto w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center mb-4">
              <MessageSquare className="w-6 h-6 text-primary" />
            </div>
            <CardTitle>AI Chat Locked</CardTitle>
            <CardDescription>Sign in to save your history and chat with the AI assistant.</CardDescription>
          </CardHeader>
          <CardContent className="flex flex-col gap-4">
            <Button className="w-full" onClick={props.onSignInClick}><LogIn className="w-4 h-4 mr-2" />Sign In</Button>
            <p className="text-[10px] text-center text-muted-foreground uppercase tracking-wider font-semibold">Code execution is available without login</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  // ── Main UI ────────────────────────────────────────────────────────────────
  return (
    <div className="flex h-full bg-background/50 backdrop-blur-sm overflow-hidden border border-border/50 shadow-inner rounded-lg">

      {/* Desktop sidebar */}
      <div className={`hidden md:block border-r border-border/50 h-full transition-all duration-300 ${sidebarOpen ? 'w-60' : 'w-0 overflow-hidden'}`}>
        <ChatSidebar
          conversations={conversations} currentId={conversationId}
          onSelect={handleSwitchConversation} onNewChat={() => setShowNewModal(true)}
          onRename={handleRenameConversation}
          onDelete={async (id) => {
            const { error } = await backendService.deleteConversation(id);
            if (!error && currentUserId) {
              const { data: convList } = await backendService.getConversations(currentUserId, 50);
              setConversations(convList || []);
              if (conversationId === id) { setConversationId(null); setCurrentTitle(""); setMessages([]); }
            }
          }}
          isOpen={true}
        />
      </div>

      {/* Mobile drawer */}
      <div className={`md:hidden fixed inset-0 z-40 bg-black/50 transition-opacity duration-300 ${showHistory ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} onClick={() => setShowHistory(false)} />
      <div className={`md:hidden fixed inset-y-0 left-0 z-50 w-72 max-w-[80vw] bg-card shadow-2xl transform transition-transform duration-300 ${showHistory ? 'translate-x-0' : '-translate-x-full'}`}>
        <ChatSidebar
          conversations={conversations} currentId={conversationId}
          onSelect={(id) => { handleSwitchConversation(id); setShowHistory(false); }}
          onNewChat={() => { setShowNewModal(true); setShowHistory(false); }}
          onRename={handleRenameConversation}
          onDelete={async (id) => {
            const { error } = await backendService.deleteConversation(id);
            if (!error && currentUserId) {
              const { data: convList } = await backendService.getConversations(currentUserId, 50);
              setConversations(convList || []);
              if (conversationId === id) { setConversationId(null); setCurrentTitle(""); setMessages([]); }
            }
          }}
          isOpen={true} onClose={() => setShowHistory(false)}
        />
      </div>

      {/* Main chat area */}
      <div className="flex-1 flex flex-col h-full min-w-0">

        {/* Header */}
        <div className="flex items-center justify-between px-2 py-2 sm:px-3 sm:py-2.5 bg-background border-b border-border shrink-0">
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="icon" className="md:hidden h-8 w-8" onClick={() => setShowHistory(true)}>
              <PanelLeft className="w-4 h-4" />
            </Button>
            <Button variant="ghost" size="icon" className="hidden md:flex h-8 w-8" onClick={() => setSidebarOpen(o => !o)}>
              <PanelLeft className="w-4 h-4" />
            </Button>
            <div className="flex items-center gap-2">
              <img src="/AicodeLogo.png" alt="AI Logo" className="w-4 h-4 sm:w-5 sm:h-5 dark-invert" />
              <h2 className="text-xs sm:text-sm font-semibold text-foreground truncate max-w-[140px] sm:max-w-xs">
                {currentTitle || "AI Assistant"}
              </h2>
            </div>
          </div>
          {/* Sembunyikan tombol New di desktop ketika sidebar terbuka */}
          <Button
            variant="ghost"
            size="sm"
            className={`h-8 px-2 text-xs gap-1.5 text-muted-foreground hover:text-foreground transition-all duration-200 ${sidebarOpen ? 'hidden md:hidden' : ''}`}
            onClick={() => setShowNewModal(true)}
          >
            <Plus className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">New</span>
          </Button>
        </div>

        {/* Global chat error alert */}
        <ErrorAlert
          message={chatError?.message ?? null}
          title={chatError?.title}
          onClose={() => setChatError(null)}
        />

        {/* No API key warning */}
        {noApiKey && !props.isChallengeActive && (
          <div className="mx-3 mt-2 flex items-start gap-2 rounded-lg border border-destructive/40 bg-destructive/10 px-3 py-2.5 text-xs text-destructive">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>
              Kamu belum menambahkan <strong>Gemini API Key</strong>. Buka menu profil (pojok kanan atas) → <strong>ADD API KEY</strong>.
            </span>
          </div>
        )}

        {/* Challenge Lock Screen */}
        {props.isChallengeActive ? (
          <div className="flex-1 flex flex-col items-center justify-start p-4 sm:p-6 overflow-y-auto gap-4 animate-in fade-in zoom-in-95 duration-500">
            <Card className="w-full max-w-sm border-dashed border-2 border-orange-500/50 bg-orange-500/5 shadow-xl">
              <CardHeader className="text-center pb-4">
                <div className="mx-auto w-16 h-16 bg-orange-500/20 rounded-full flex items-center justify-center mb-4 shadow-inner">
                  <span className="text-3xl">🎯</span>
                </div>
                <CardTitle className="text-xl text-orange-600 dark:text-orange-400 font-bold tracking-tight">Mode Latihan Aktif</CardTitle>
                <CardDescription className="text-sm mt-2 text-muted-foreground leading-relaxed">
                  AI Chat dinonaktifkan sementara. Uji kemampuanmu dan selesaikan tantangan ngoding ini <strong>tanpa bantuan AI</strong>!
                </CardDescription>
              </CardHeader>
              <CardContent className="text-center">
                <p className="text-[10px] sm:text-xs text-orange-600/70 font-medium mb-4">Hapus atau ubah teks "# 🎯 TANTANGAN" di dalam cell untuk mengaktifkan AI kembali.</p>
                {props.onRemoveChallenge && (
                  <Button 
                    variant="outline" 
                    className="w-full border-orange-500/30 hover:bg-orange-500/10 hover:text-orange-600"
                    onClick={props.onRemoveChallenge}
                  >
                    🏳️ Menyerah
                  </Button>
                )}
              </CardContent>
            </Card>

            {/* Tampilkan feedback cek jawaban terakhir */}
            {lastChallengeHint && (
              <div className="w-full max-w-sm animate-in fade-in slide-in-from-bottom-3 duration-400">
                <div className={`rounded-xl border p-4 text-left shadow-md ${
                  lastChallengeHint.includes("✅ LULUS") || lastChallengeHint.includes("LULUS:")
                    ? "bg-emerald-500/5 border-emerald-500/40"
                    : "bg-secondary/60 border-border/50"
                }`}>
                  <div className="flex items-center gap-2 mb-2.5">
                    <span className="text-base">🤖</span>
                    <span className="text-xs font-semibold text-foreground/80">Feedback Cek Jawaban</span>
                  </div>
                  <ChatMessageBubble role="assistant" content={lastChallengeHint} animate={false} />
                </div>
              </div>
            )}
          </div>
        ) : (
          <>
            {/* Messages */}
            <div className="flex-1 min-h-0 overflow-auto p-2 sm:p-4 space-y-3 sm:space-y-4">
              {loadingHistory && (
            <div className="flex justify-center py-6 text-muted-foreground text-sm">Loading history...</div>
          )}
          {messages.length === 0 && !loadingHistory ? (
            <div className="h-full flex items-center justify-center text-center text-muted-foreground max-w-md mx-auto">
              <div>
                <img src="/AicodeLogo.png" alt="AI" className="w-10 h-10 mx-auto mb-3 opacity-40 dark-invert" />
                <p className="text-sm">Ask me anything about Python!</p>
                {noApiKey && <p className="text-xs mt-2 text-destructive/80">Missing API key — chat is disabled.</p>}
              </div>
            </div>
          ) : (
            messages.map((msg, idx) => {
              // Hide empty streaming placeholder while status indicator shows
              if (isLoading && aiStage !== 'idle' && idx === messages.length - 1 && msg.role === 'assistant' && !msg.content) return null;
              return (
                <div key={idx} className={`flex flex-col ${msg.role === "user" ? "items-end" : "items-start"}`}>
                  <div className={`
                    ${msg.role === "user" ? "max-w-[85%]" : "max-w-[98%] w-full"}
                    rounded-xl px-2.5 py-1.5 sm:px-3.5 sm:py-2.5
                    ${msg.role === "user"
                      ? "bg-primary text-primary-foreground"
                      : "text-foreground bg-secondary/40 border border-border/40"
                    }
                  `}>
                    <ChatMessageBubble
                      role={msg.role}
                      content={msg.content}
                      animate={
                        (isLoading && idx === messages.length - 1 && msg.role === "assistant") ||
                        (!!msg.animateOnAdd && idx === messages.length - 1 && msg.role === "assistant")
                      }
                    />
                  </div>
                  {/* Token info — hanya tampil di pesan AI yang punya data token */}
                  {msg.role === "assistant" && msg.inputTokens !== undefined && msg.outputTokens !== undefined && (
                    <div className="flex items-center gap-1 mt-0.5 px-1 text-[10px] text-muted-foreground/50 select-none">
                      <span>⚡</span>
                      <span>{msg.inputTokens.toLocaleString()} in</span>
                      <span>·</span>
                      <span>{msg.outputTokens.toLocaleString()} out</span>
                      <span>·</span>
                      <span>{(msg.inputTokens + msg.outputTokens).toLocaleString()} tok</span>
                    </div>
                  )}
                </div>
              );
            })
          )}

          <AIStatusIndicator stage={aiStage} />

          {/* Banner: tampil saat Groq backup sedang streaming */}
          {usingFallback && (
            <div className="flex justify-start animate-in fade-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center gap-1.5 text-xs font-medium text-amber-600 dark:text-amber-400 border border-amber-300 dark:border-amber-700/60 bg-amber-50 dark:bg-amber-950/30 rounded-full px-3 py-1 shadow-sm">
                <span>⚡</span>
                <span>AI Sedang Memberikan Jawaban</span>
                <Loader2 className="w-3 h-3 animate-spin ml-0.5" />
              </div>
            </div>
          )}

          {isLoading && aiStage === 'idle' && (
            <div className="flex justify-start">
              <div className="bg-secondary text-secondary-foreground rounded-xl px-4 py-2.5">
                <Loader2 className="w-4 h-4 animate-spin" />
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input bar */}
        <ChatInputForm onSend={handleSend} isLoading={isLoading} noApiKey={noApiKey} />
      </>
      )}
    </div>

      {/* New Chat Modal */}
      {showNewModal && (
        <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4" onClick={() => setShowNewModal(false)}>
          <div className="bg-card border border-border rounded-xl shadow-2xl w-full max-w-sm p-5" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-semibold text-foreground">New Conversation</h3>
              <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setShowNewModal(false)}>
                <X className="w-4 h-4" />
              </Button>
            </div>
            <label className="text-xs text-muted-foreground font-medium">Title</label>
            <input
              className="w-full mt-1.5 mb-4 px-3 py-2 bg-background border border-border rounded-lg outline-none text-sm focus:ring-2 focus:ring-primary/20 text-foreground placeholder:text-muted-foreground transition-all"
              value={newChatTitle}
              onChange={(e) => setNewChatTitle(e.target.value)}
              placeholder={`Chat ${new Date().toLocaleDateString()}`}
              autoFocus
            />
            <div className="flex justify-end gap-2">
              <Button variant="outline" size="sm" onClick={() => setShowNewModal(false)}>Cancel</Button>
              <Button size="sm" onClick={async () => {
                const user = authService.getUser();
                if (!user) return;
                const userId = user.id;
                
                // 1. Close modal and show loading immediately
                setShowNewModal(false);
                setLoadingHistory(true);
                
                // 2. Fire and forget auto-save (don't block)
                if (conversationId && props.getCurrentCode) {
                  const code = props.getCurrentCode();
                  if (code?.trim()) {
                    backendService.saveCodeSnippet(userId, code, "python", conversationId, `Auto-save ${new Date().toLocaleTimeString()}`).catch(console.warn);
                  }
                }
                
                // 3. Create conversation in backend
                const { data: conv, error } = await backendService.createConversation(userId, newChatTitle || "New Chat");
                
                if (!error && conv) {
                  setConversationId(conv.id);
                  setCurrentTitle(conv.title || "Untitled");
                  setMessages([]);
                  if (props.onLoadCode) props.onLoadCode(""); // Clear editor instantly
                  
                  // Optimistically add to sidebar immediately before fetching
                  setConversations(prev => [{ id: conv.id, title: conv.title, created_at: new Date().toISOString() }, ...prev]);
                  
                  // Refetch list in background to sync exactly
                  backendService.getConversations(userId, 50).then(res => {
                    if (res.data) setConversations(res.data);
                  });
                }
                
                setLoadingHistory(false);
                setNewChatTitle(""); // reset input for next time
              }}>Create</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
});

import { useRef, useState, useEffect } from "react";
import { Editor } from "@monaco-editor/react";
import { Button } from "@/components/ui/button";
import { Play, Trash2, SquareTerminal, Loader2, Download, Upload } from "lucide-react";
import { useTheme } from "next-themes";
import { DebugButton } from "./DebugButton";
import { useToast } from "@/hooks/use-toast";

interface CodeEditorProps {
  code: string;
  onChange: (value: string) => void;
  onRun: () => void;
  onClear: () => void;
  showTerminal?: boolean;
  onToggleTerminal?: () => void;
  lastError?: string | null;
  onDebug?: (message: string) => void;
  isRuntimeReady?: boolean;
  isRunning?: boolean;
}

export const CodeEditor = ({
  code,
  onChange,
  onRun,
  onClear,
  showTerminal = true,
  onToggleTerminal,
  lastError,
  onDebug,
  isRuntimeReady = true,
  isRunning = false,
}: CodeEditorProps) => {
  const { resolvedTheme } = useTheme();
  const { toast } = useToast();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);

  const handleEditorWillMount = (monaco: any) => {
    // ── Custom Dark Theme (VS Code inspired, synced ke app bg) ─────────────────
    monaco.editor.defineTheme('custom-dark', {
      base: 'vs-dark',
      inherit: true,
      rules: [
        // Keywords: def, class, return, if, for, while, import, from, as, with, ...
        { token: 'keyword', foreground: 'c792ea' },  // 🟣 ungu
        { token: 'keyword.control', foreground: 'f97583' },  // 🔴 merah muda
        // Built-in functions: print, len, range, type, input, ...
        { token: 'support.function', foreground: 'ffcb6b' },  // 🟡 kuning emas
        // String literals
        { token: 'string', foreground: 'c3e88d' },  // 🟢 hijau muda
        { token: 'string.escape', foreground: 'f78c6c' },  // 🟠 oranye (escape char)
        // Comments
        { token: 'comment', foreground: '546e7a', fontStyle: 'italic' },
        // Numbers
        { token: 'number', foreground: 'f78c6c' },  // 🟠 oranye
        { token: 'number.float', foreground: 'f78c6c' },
        // Function & class names
        { token: 'entity.name.function', foreground: '82aaff' },  // 🔵 biru
        { token: 'entity.name.class', foreground: 'ffcb6b' },  // 🟡 kuning
        // Self, True, False, None
        { token: 'variable.language', foreground: 'f07178' },  // 🔴 merah muda
        { token: 'constant.language', foreground: 'ff5370' },  // 🔴 merah
        // Operators: =, +, -, *, /, ==, !=, ...
        { token: 'operator', foreground: '89ddff' },  // 🩵 biru muda
        // Decorator: @staticmethod, @property, ...
        { token: 'meta.decorator', foreground: 'c792ea' },
        // Type hints
        { token: 'entity.name.type', foreground: 'ffcb6b' },
      ],
      colors: {
        'editor.background': '#09090b', // zinc-950 — cocok dgn app bg
        'editor.foreground': '#cdd3de',
        'editor.lineHighlightBackground': '#ffffff08',
        'editor.selectionBackground': '#4a4a7a66',
        'editorCursor.foreground': '#c792ea',
        'editorLineNumber.foreground': '#37474f',
        'editorLineNumber.activeForeground': '#78909c',
        'editorIndentGuide.background': '#ffffff10',
        'editorGutter.background': '#09090b',
      }
    });

    // ── Custom Light Theme (high contrast, tetap nyaman dibaca) ────────────────
    monaco.editor.defineTheme('custom-light', {
      base: 'vs',
      inherit: true,
      rules: [
        { token: 'keyword', foreground: '7c3aed' },  // 🟣 ungu gelap
        { token: 'keyword.control', foreground: 'd63031' },  // 🔴 merah
        { token: 'support.function', foreground: 'b45309' },  // 🟡 coklat-kuning
        { token: 'string', foreground: '16803a' },  // 🟢 hijau gelap
        { token: 'string.escape', foreground: 'd97706' },  // 🟠 oranye
        { token: 'comment', foreground: '94a3b8', fontStyle: 'italic' },
        { token: 'number', foreground: 'c2410c' },  // 🟠 oranye tua
        { token: 'number.float', foreground: 'c2410c' },
        { token: 'entity.name.function', foreground: '1d4ed8' },  // 🔵 biru gelap
        { token: 'entity.name.class', foreground: 'b45309' },
        { token: 'variable.language', foreground: 'be185d' },  // 🩷 pink gelap
        { token: 'constant.language', foreground: 'be185d' },
        { token: 'operator', foreground: '0369a1' },  // 🔵 biru muda gelap
        { token: 'entity.name.type', foreground: 'b45309' },
      ],
      colors: {
        'editor.background': '#fafafa',
        'editor.foreground': '#1e293b',
        'editor.lineHighlightBackground': '#00000008',
        'editor.selectionBackground': '#7c3aed22',
        'editorCursor.foreground': '#7c3aed',
        'editorLineNumber.foreground': '#94a3b8',
        'editorLineNumber.activeForeground': '#475569',
        'editorIndentGuide.background': '#00000015',
      }
    });
  };

  // ── Save as .py ────────────────────────────────────────────────────────────
  const handleSavePy = () => {
    try {
      const blob = new Blob([code], { type: 'text/x-python' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'code.py';
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast({ title: 'Gagal Menyimpan', description: 'Tidak bisa menyimpan file. Coba lagi.', variant: 'destructive' });
    }
  };

  // ── Import .py ─────────────────────────────────────────────────────────────
  const handleImportPy = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.name.endsWith('.py')) {
      toast({ title: 'Format Tidak Didukung', description: 'Hanya file .py yang dapat diimport.', variant: 'destructive' });
      e.target.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = (ev) => {
      const content = ev.target?.result as string;
      onChange(content);
      toast({ title: 'File Diimport', description: `${file.name} berhasil dimuat.`, duration: 2000 });
    };
    reader.onerror = () => {
      toast({ title: 'Gagal Membaca File', description: 'File tidak bisa dibaca. Coba lagi.', variant: 'destructive' });
    };
    reader.readAsText(file);
    e.target.value = ''; // reset so same file can be re-imported
  };

  return (
    <div className="flex flex-col h-full bg-editor-bg rounded-lg overflow-hidden border border-border shadow-card">
      {/* ── Toolbar ───────────────────────────────────────────────────────────── */}
      <div className="flex items-center justify-between px-1.5 sm:px-4 py-1.5 sm:py-3 bg-secondary border-b border-border shrink-0">
        <div className="flex items-center gap-2 sm:gap-3">
          <div className="flex gap-1 sm:gap-1.5 items-center mr-1 sm:mr-3">
            <div className="w-2.5 sm:w-3 h-2.5 sm:h-3 rounded-full bg-red-400/80" />
            <div className="w-2.5 sm:w-3 h-2.5 sm:h-3 rounded-full bg-amber-400/80" />
            <div className="w-2.5 sm:w-3 h-2.5 sm:h-3 rounded-full bg-green-400/80" />
          </div>
          <span className="text-[10px] sm:text-sm font-semibold text-foreground/80 font-mono tracking-tight flex items-center gap-1 sm:gap-2">
            main.py
            <span className="hidden xs:inline text-[9px] sm:text-[10px] text-muted-foreground px-1.5 py-0.5 rounded-md bg-secondary border border-border">Python 3.10</span>
          </span>
        </div>

        <div className="flex items-center gap-1 sm:gap-2">
          {/* Action buttons (icon only on mobile) */}
          {onToggleTerminal && (
            <Button
              size="sm"
              variant="ghost"
              onClick={onToggleTerminal}
              className={`h-8 w-8 sm:w-auto px-0 sm:px-2.5 gap-1.5 ${showTerminal ? 'bg-muted text-foreground' : 'text-muted-foreground hover:text-foreground'}`}
              title={showTerminal ? "Hide Terminal" : "Show Terminal"}
            >
              <SquareTerminal className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
              <span className="hidden sm:inline text-xs">Terminal</span>
            </Button>
          )}

          <input
            type="file"
            accept=".py"
            ref={fileInputRef}
            onChange={handleImportPy}
            className="hidden"
          />
          <Button
            size="sm"
            variant="ghost"
            onClick={() => fileInputRef.current?.click()}
            title="Import .py (Ctrl+O)"
            className="h-8 w-8 sm:w-auto px-0 sm:px-2.5 gap-1.5 text-muted-foreground hover:text-foreground"
          >
            <Upload className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
            <span className="hidden sm:inline text-xs">Import</span>
          </Button>

          <Button
            size="sm"
            variant="ghost"
            onClick={handleSavePy}
            disabled={!code.trim()}
            title="Save .py (Ctrl+S)"
            className="h-8 w-8 sm:w-auto px-0 sm:px-2.5 gap-1.5 text-muted-foreground hover:text-foreground disabled:opacity-40"
          >
            <Download className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
            <span className="hidden sm:inline text-xs">Save</span>
          </Button>

          <div className="w-px h-4 bg-border mx-0 sm:mx-1 hidden xs:block" />

          {onClear && (
            <Button
              size="sm"
              variant="outline"
              onClick={onClear}
              title="Clear terminal output"
              className="h-8 w-8 sm:w-auto px-0 sm:px-2.5 gap-1.5 ml-0 sm:ml-1"
            >
              <Trash2 className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
              <span className="hidden sm:inline text-xs">Clear</span>
            </Button>
          )}

          <Button
            size="sm"
            onClick={onRun}
            disabled={!isRuntimeReady || isRunning}
            title={!isRuntimeReady ? "Loading Python runtime..." : isRunning ? "Code is executing..." : "Run code (Ctrl+Enter)"}
            className="h-7 px-2 sm:h-8 sm:px-4 text-[11px] sm:text-xs font-medium gap-1 sm:gap-1.5 bg-accent text-accent-foreground hover:bg-accent/90 hover:shadow-glow-accent transition-all disabled:opacity-60"
          >
            {(!isRuntimeReady || isRunning) ? <Loader2 className="w-3.5 h-3.5 sm:w-4 sm:h-4 animate-spin" /> : <Play className="w-3.5 h-3.5 sm:w-4 sm:h-4" />}
            <span className="hidden xs:inline">{!isRuntimeReady ? "Wait" : isRunning ? "Running" : "Run"}</span>
          </Button>
          {onDebug && (
            <DebugButton
              code={code}
              lastError={lastError ?? null}
              onSendMessage={onDebug}
            />
          )}
        </div>
      </div>

      {/* Editor */}
      <div className="flex-1 overflow-hidden">
        <Editor
          height="100%"
          defaultLanguage="python"
          value={code}
          onChange={(value) => onChange(value || "")}
          theme={resolvedTheme === 'dark' ? 'custom-dark' : 'custom-light'}
          beforeMount={handleEditorWillMount}
          options={{
            minimap: { enabled: false },
            fontSize: isMobile ? 12 : 14,
            fontFamily: "JetBrains Mono, Fira Code, monospace",
            lineHeight: isMobile ? 20 : 24,
            lineNumbers: "on",
            scrollBeyondLastLine: false,
            automaticLayout: true,
            tabSize: 4,
            padding: { top: 16, bottom: 16 },
            smoothScrolling: true,
            cursorBlinking: "smooth",
            cursorSmoothCaretAnimation: "on",
            wordWrap: "on",
          }}
        />
      </div>
    </div>
  );
};

import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Code, Play, MessageSquare, Zap, Cpu, Terminal } from "lucide-react";

interface LandingPageProps {
  onGetStarted: () => void;
}

export const LandingPage = ({ onGetStarted }: LandingPageProps) => {
  const [isVisible, setIsVisible] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Intersection Observer hook
  const useScrollAnimation = () => {
    const ref = useRef<HTMLDivElement>(null);
    const [isIntersecting, setIntersecting] = useState(false);

    useEffect(() => {
      const observer = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) {
            setIntersecting(true);
          } else {
            setIntersecting(false);
          }
        },
        { threshold: 0.1 }
      );

      if (ref.current) {
        observer.observe(ref.current);
      }

      return () => {
        if (ref.current) observer.unobserve(ref.current);
      };
    }, []);

    return [ref, isIntersecting] as const;
  };

  const [heroRef, heroVisible] = useScrollAnimation();
  const [featureRef1, feature1Visible] = useScrollAnimation();
  const [featureRef2, feature2Visible] = useScrollAnimation();
  const [featureRef3, feature3Visible] = useScrollAnimation();
  const [featuresRef, featuresVisible] = useScrollAnimation();

  useEffect(() => {
    setIsVisible(true);
  }, []);

  // ── Particle Effect ──────────────────────────────────────────────────────────
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    const COLORS = [
      'rgba(139, 92, 246, ',   // violet
      'rgba(99, 102, 241, ',   // indigo
      'rgba(59, 130, 246, ',   // blue
      'rgba(168, 85, 247, ',   // purple
    ];

    type Particle = {
      x: number; y: number;
      r: number; speed: number;
      drift: number; opacity: number;
      color: string; pulse: number;
    };

    const makeParticle = (): Particle => ({
      x: Math.random() * canvas.width,
      y: canvas.height + Math.random() * 100,
      r: Math.random() * 2.5 + 0.5,
      speed: Math.random() * 0.6 + 0.2,
      drift: (Math.random() - 0.5) * 0.4,
      opacity: Math.random() * 0.5 + 0.15,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
      pulse: Math.random() * Math.PI * 2,
    });

    const particles: Particle[] = Array.from({ length: 90 }, makeParticle);
    // Scatter initial positions vertically
    particles.forEach(p => { p.y = Math.random() * canvas.height; });

    let animId: number;
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      particles.forEach(p => {
        p.pulse += 0.015;
        const alpha = p.opacity * (0.8 + 0.2 * Math.sin(p.pulse));
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `${p.color}${alpha.toFixed(2)})`;
        ctx.fill();

        p.y -= p.speed;
        p.x += p.drift;

        if (p.y < -10) {
          Object.assign(p, makeParticle());
        }
      });
      animId = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(animId);
      window.removeEventListener('resize', resize);
    };
  }, []);

  return (
    <div className="min-h-screen bg-background text-foreground overflow-x-hidden">
      {/* Hero Section */}
      <section
        className={`relative min-h-screen flex flex-col items-center justify-center p-6 text-center transition-all duration-1000 transform ${isVisible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
      >
        {/* Particle Canvas */}
        <canvas
          ref={canvasRef}
          className="absolute inset-0 w-full h-full pointer-events-none"
          style={{ zIndex: 0 }}
        />
        {/* Content above particles */}
        <div className="relative z-10 flex flex-col items-center">
          <div className="relative mb-8 group">
            <div className="absolute inset-0 bg-primary/20 rounded-full blur-3xl group-hover:bg-primary/30 transition-all duration-700"></div>
            <img
              src="/AicodeLogo.png"
              alt="AIcode Logo"
              className="w-32 h-32 sm:w-48 sm:h-48 relative z-10 drop-shadow-2xl transition-transform duration-700 hover:scale-110 cursor-pointer dark-invert"
              draggable={false}
            />
          </div>

          <h1 className="text-2xl sm:text-3xl md:text-5xl font-bold mb-4 sm:mb-6 bg-clip-text text-transparent bg-gradient-to-r from-primary via-purple-500 to-blue-600 animate-in fade-in slide-in-from-bottom-4 duration-1000">
            AI Code Assistant
          </h1>

          <p className="text-sm sm:text-xl md:text-2xl text-muted-foreground max-w-2xl mb-8 sm:mb-12 leading-relaxed animate-in fade-in slide-in-from-bottom-8 duration-1000 delay-200">
            Experience the future of coding. Write Python, run it instantly, and get AI-powered assistance in real-time.
          </p>

          <div className="animate-in fade-in slide-in-from-bottom-12 duration-1000 delay-300">
            <Button
              onClick={onGetStarted}
              size="lg"
              className="text-base px-6 py-4 sm:text-lg sm:px-10 sm:py-6 rounded-full shadow-lg shadow-primary/25 hover:shadow-primary/40 hover:scale-105 transition-all duration-300"
            >
              Start Coding Now
            </Button>
          </div>
        </div> {/* end z-10 wrapper */}

        <div className="absolute bottom-10 animate-bounce z-10">
          <p className="text-sm text-muted-foreground mb-2">Scroll to learn more</p>
          <div className="w-6 h-10 border-2 border-muted-foreground rounded-full mx-auto flex justify-center p-1">
            <div className="w-1 h-2 bg-muted-foreground rounded-full animate-pulse"></div>
          </div>
        </div>
      </section>

      {/* How it works Section */}
      <section
        id="how-it-works"
        ref={featuresRef}
        className={`py-32 px-6 bg-secondary/30 transition-opacity duration-1000 ${featuresVisible ? 'opacity-100' : 'opacity-0'}`}
      >
        <div className="max-w-7xl mx-auto">
          <h2 className="text-2xl md:text-5xl font-bold text-center mb-16 sm:mb-24 bg-clip-text text-transparent bg-gradient-to-br from-foreground to-muted-foreground">
            How to use AI Coding Assistants
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
            {/* Feature 1 */}
            <div
              ref={featureRef1}
              className={`p-8 rounded-2xl bg-card border border-border/50 shadow-xl hover:shadow-2xl hover:border-primary/50 transition-all duration-700 transform ${feature1Visible ? "opacity-100 translate-x-0" : "opacity-0 -translate-x-20"
                }`}
            >
              <div className="w-16 h-16 bg-blue-900/20 rounded-2xl flex items-center justify-center mb-6 text-blue-400">
                <Code className="w-8 h-8" />
              </div>
              <h3 className="text-xl sm:text-2xl font-bold mb-4">1. Write & Edit</h3>
              <p className="text-muted-foreground leading-relaxed">
                Use the powerful code editor to write your Python scripts. It supports syntax highlighting, auto-formatting, and intelligent suggestions to keep your code clean.
              </p>
            </div>

            {/* Feature 2 */}
            <div
              ref={featureRef2}
              className={`p-8 rounded-2xl bg-card border border-border/50 shadow-xl hover:shadow-2xl hover:border-primary/50 transition-all duration-700 delay-200 transform ${feature2Visible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-20"
                }`}
            >
              <div className="w-16 h-16 bg-green-900/20 rounded-2xl flex items-center justify-center mb-6 text-green-400">
                <Play className="w-8 h-8" />
              </div>
              <h3 className="text-xl sm:text-2xl font-bold mb-4">2. Run Instantly</h3>
              <p className="text-muted-foreground leading-relaxed">
                Execute your code directly in the browser with our embedded Python runtime. See output instantly in the integrated terminal without any server setup.
              </p>
            </div>

            {/* Feature 3 */}
            <div
              ref={featureRef3}
              className={`p-8 rounded-2xl bg-card border border-border/50 shadow-xl hover:shadow-2xl hover:border-primary/50 transition-all duration-700 delay-400 transform ${feature3Visible ? "opacity-100 translate-x-0" : "opacity-0 translate-x-20"
                }`}
            >
              <div className="w-16 h-16 bg-purple-900/20 rounded-2xl flex items-center justify-center mb-6 text-purple-400">
                <MessageSquare className="w-8 h-8" />
              </div>
              <h3 className="text-xl sm:text-2xl font-bold mb-4">3. AI Assistance</h3>
              <p className="text-muted-foreground leading-relaxed">
                Stuck? Ask the AI assistant to debug your code, explain concepts, or suggest improvements. It's like having a senior developer pair-programming with you.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Advanced Features */}
      <section className="py-32 px-6">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row gap-16 items-center">
          <div className="space-y-12 flex-1">
            <div className="flex items-start gap-6 group">
              <div className="p-4 bg-primary/10 rounded-2xl text-primary group-hover:scale-110 transition-transform duration-300">
                <Zap className="w-8 h-8" />
              </div>
              <div>
                <h3 className="text-2xl font-bold mb-2 group-hover:text-primary transition-colors">Lightning Fast Execution</h3>
                <p className="text-muted-foreground text-lg">Local execution means zero latency. Your code runs instantly in your browser without waiting for server round-trips.</p>
              </div>
            </div>
            <div className="flex items-start gap-6 group">
              <div className="p-4 bg-primary/10 rounded-2xl text-primary group-hover:scale-110 transition-transform duration-300">
                <Cpu className="w-8 h-8" />
              </div>
              <div>
                <h3 className="text-2xl font-bold mb-2 group-hover:text-primary transition-colors">Browser-Based Runtime</h3>
                <p className="text-muted-foreground text-lg">No installation required. Our advanced runtime works on any device with a modern web browser, powered by WebAssembly.</p>
              </div>
            </div>
            <div className="flex items-start gap-6 group">
              <div className="p-4 bg-primary/10 rounded-2xl text-primary group-hover:scale-110 transition-transform duration-300">
                <Terminal className="w-8 h-8" />
              </div>
              <div>
                <h3 className="text-2xl font-bold mb-2 group-hover:text-primary transition-colors">Interactive Terminal</h3>
                <p className="text-muted-foreground text-lg">Full standard input/output support. Build interactive CLI tools, games, and data scripts effortlessly.</p>
              </div>
            </div>
          </div>
          <div className="flex-1 w-full relative group">
            <div className="absolute -inset-1 bg-gradient-to-r from-primary to-purple-600 rounded-2xl blur opacity-30 group-hover:opacity-60 transition duration-1000"></div>
            <div className="relative bg-black/80 backdrop-blur-xl border border-white/10 rounded-xl p-8 shadow-2xl overflow-hidden">
              <div className="flex gap-2 mb-4">
                <div className="w-3 h-3 rounded-full bg-red-500"></div>
                <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
                <div className="w-3 h-3 rounded-full bg-green-500"></div>
              </div>
              <pre className="text-sm md:text-base font-mono text-muted-foreground font-medium">
                <span className="text-purple-400">def</span> <span className="text-blue-400">welcome</span>(user):{'\n'}
                {'    '}print(<span className="text-green-400">f"Hello, &#123;user&#125;!"</span>){'\n'}
                {'    '}ai_assist.start_session(){'\n'}
                {'\n'}
                <span className="text-slate-500"># Start coding journey</span>{'\n'}
                welcome(<span className="text-green-400">"Developer"</span>)
              </pre>
            </div>
          </div>
        </div>
      </section>

      {/* Data Privacy & Transparency Section */}
      <section className="py-20 px-6 bg-background/50 border-t border-border">
        <div className="max-w-4xl mx-auto text-center">
          <h2 className="text-2xl font-bold mb-6">Data Privacy & Transparency</h2>
          <p className="text-muted-foreground leading-relaxed mb-4">
            At <strong>aicode-unklab</strong>, we value your privacy. We use Google OAuth to securely authenticate users and provide a personalized experience.
          </p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-8 text-left">
            <div className="p-6 rounded-xl bg-card border border-border">
              <h4 className="font-bold mb-2 text-primary">Why we collect data?</h4>
              <p className="text-sm text-muted-foreground">We request your email and basic profile info to create your account and allow you to save/load your Python code snippets across devices.</p>
            </div>
            <div className="p-6 rounded-xl bg-card border border-border">
              <h4 className="font-bold mb-2 text-primary">How we use it?</h4>
              <p className="text-sm text-muted-foreground">Your data is only used for authentication and to store your personal projects. We never share your data with third parties or use it for advertising.</p>
            </div>
          </div>
        </div>
      </section>

      <footer className="py-12 bg-secondary/50 text-center text-muted-foreground border-t border-border">
        <div className="flex flex-col items-center gap-4">
          <img src="/AicodeLogo.png" alt="Logo" className="w-12 h-12 grayscale opacity-50 hover:grayscale-0 hover:opacity-100 transition-all duration-500" />
          <p className="text-sm">© {new Date().getFullYear()} aicode-unklab. Built for developers.</p>
          <div className="flex gap-6 mt-2">
            <a href="https://unklab-aicode.online/privacy" className="text-xs hover:text-primary transition-colors underline-offset-4 hover:underline">Privacy Policy</a>
            <a href="https://unklab-aicode.online/terms" className="text-xs hover:text-primary transition-colors underline-offset-4 hover:underline">Terms of Service</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

import { useRef, useState, useEffect, useCallback, forwardRef, useImperativeHandle } from "react";
import { Editor } from "@monaco-editor/react";
import { Button } from "@/components/ui/button";
import {
  Play, Loader2, Plus, Trash2, ChevronUp, ChevronDown, ChevronRight,
  Sparkles, Bug, BookOpen, Download, Upload, X, Zap, Square,
  Save, CheckCircle2, AlertCircle, Target, Sparkles as SparklesIcon,
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useTheme } from "next-themes";
import { useToast } from "@/hooks/use-toast";
import { authService } from "@/services/authService";
import { fetchUserApiKey, streamGeminiResponse } from "@/services/geminiService";
import { streamGroqFallback } from "@/services/groqFallbackService";
