import { createContext, useContext, useState, ReactNode, useEffect } from "react";
import { authService, User } from "@/services/authService";
import { clearCachedApiKey } from "@/services/geminiService";

interface AuthContextType {
  user: User | null;
  login: (user: User) => void;
  logout: () => void;
  isAuthenticated: boolean;
  isLoading: boolean;
}

const AuthContext = createContext<AuthContextType | null>(null);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // On every app load, hit /api/me to see if the browser still has a valid session cookie.
    // This replaces the old localStorage-based check.
    const init = async () => {
      try {
        const verifiedUser = await authService.initSession();
        setUser(verifiedUser);
      } catch (e) {
        setUser(null);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  const login = (userData: User) => {
    setUser(userData);
  };

  const logout = async () => {
    await authService.logout();
    clearCachedApiKey(); // clear in-memory Gemini key cache
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, isAuthenticated: !!user, isLoading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Loader2 } from 'lucide-react';
import { getSupabaseClient } from '@/lib/supabaseClient';
import { useAuth } from '@/context/AuthContext';
import { API_BASE_URL } from '@/config';

export default function AuthCallback() {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [error, setError] = useState<string | null>(null);

  // ✅ FIX: Guard agar handleSession hanya dipanggil SEKALI
  const handledRef = useRef(false);

  useEffect(() => {
    let isMounted = true;

    const handleSession = async (session: any) => {
      // Bail jika sudah diproses atau komponen unmount
      if (!session || !isMounted || handledRef.current) return;
      handledRef.current = true; // ← LOCK: tidak akan dipanggil lagi

      try {
        // Step 1: Set HttpOnly cookies di backend
        const setSessionRes = await fetch(`${API_BASE_URL}/auth/set-session`, {
          method: 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            access_token: session.access_token,
            refresh_token: session.refresh_token ?? ''
          })
        });

        if (!setSessionRes.ok) {
          const errData = await setSessionRes.json().catch(() => ({}));
          throw new Error(errData.error || 'Failed to establish secure session');
        }

        // Step 2: Build user object dari Supabase session
        const user = session.user;
        const metadata = user.user_metadata || {};
        const username =
          metadata.username ||
          metadata.full_name ||
          metadata.name ||
          user.email?.split('@')[0] ||
          'User';

        // Step 3: Update React state
        login({
          id: user.id,
          email: user.email || '',
          username,
        });

        // Step 4: Bersihkan hash dari URL lalu redirect ke home
        window.history.replaceState(null, '', window.location.pathname);
        if (isMounted) navigate('/', { replace: true });

      } catch (err: any) {
        handledRef.current = false; // Reset agar error bisa di-retry
        if (isMounted) {
          console.error('[AuthCallback] Error:', err);
          setError(err?.message || 'Authentication failed. Please try again.');
        }
      }
    };

    const initAuth = async () => {
      const supabase = await getSupabaseClient();

      // Cara paling reliable: langsung getSession() saja
      // onAuthStateChange kadang fire berkali-kali — kita tidak pakai itu
      const { data: { session }, error: sessionErr } = await supabase.auth.getSession();

      if (sessionErr) {
        console.error('[AuthCallback] getSession error:', sessionErr);
        if (isMounted) setError('Failed to retrieve session. Please try again.');
        return;
      }

      if (session) {
        await handleSession(session);
      } else {
        // Session tidak ada setelah menunggu — kemungkinan link sudah expired
        if (isMounted) setError('Session tidak ditemukan. Silakan login kembali.');
      }
    };

    initAuth();

    return () => {
      isMounted = false;
    };
  }, []); // ← Empty deps: hanya run sekali saat komponen mount

  if (error) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-background gap-4 p-4">
        <div className="w-full max-w-md bg-card/50 backdrop-blur-xl border border-destructive/50 rounded-2xl p-8 text-center shadow-2xl">
          <div className="w-12 h-12 rounded-full bg-destructive/10 flex items-center justify-center mx-auto mb-4">
            <svg className="w-6 h-6 text-destructive" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </div>
          <h2 className="text-xl font-bold text-foreground mb-2">Authentication Failed</h2>
          <p className="text-sm text-muted-foreground mb-6">{error}</p>
          <button
            onClick={() => navigate('/') }
            className="text-sm font-semibold text-primary hover:underline"
          >
            Return to Home
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-background gap-4">
      <div className="absolute top-[-20%] left-[-10%] w-[500px] h-[500px] bg-primary/20 rounded-full blur-[100px] animate-pulse pointer-events-none" />
      <div className="absolute bottom-[-20%] right-[-10%] w-[500px] h-[500px] bg-purple-500/20 rounded-full blur-[100px] animate-pulse pointer-events-none" />
      <div className="relative flex flex-col items-center gap-4">
        <Loader2 className="w-12 h-12 animate-spin text-primary" />
        <p className="text-muted-foreground text-sm font-medium">Completing sign in with Google...</p>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { Panel, PanelGroup, PanelResizeHandle } from "react-resizable-panels";
import { NotebookEditor, type NotebookEditorHandle } from "@/components/NotebookEditor";
import { ChatInterface, ChatInterfaceHandle } from "@/components/ChatInterface";
import { Navbar } from "@/components/Navbar";
import { AuthScreen } from "@/components/AuthScreen";
import { loadSkulpt } from "@/utils/skulptRunner";
import { useToast } from "@/hooks/use-toast";
import { LandingPage } from "@/components/LandingPage";
import { Particles } from "@/components/ui/Particles";
import { Helmet } from "react-helmet-async";
import { useLocation } from "react-router-dom";
import { Code, MessageSquare } from "lucide-react";
import { backendService } from "@/services/backendService";
import { authService } from "@/services/authService";

// ── Mobile tab type (code | chat) ───────────────────────────────────────────
type MobileTab = "code" | "chat";

const Index = () => {
  const location = useLocation();
  const [code, setCode] = useState(`# Selamat datang di AI Coding Assistant!\n# Tulis kode Python kamu di sini dan klik Run per cell\n\nprint("Halo, Dunia! Selamat belajar Python!")\n`);
  const [showStart, setShowStart] = useState(true);
  const [skulptReady, setSkulptReady] = useState(false);
  const { toast } = useToast();
  const chatRef = useRef<ChatInterfaceHandle | null>(null);
  const notebookRef = useRef<NotebookEditorHandle | null>(null);
  const [showAuth, setShowAuth] = useState(false);
  const [viewMode, setViewMode] = useState<"code" | "chat" | "both">("both");

  // ── Mobile detection & default tab ─────────────────────────────────────────
  const [isMobile, setIsMobile] = useState(false);
  const [mobileTab, setMobileTab] = useState<MobileTab>("chat");

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);

  useEffect(() => {
    if (location.state?.showLanding) {
      setShowStart(true);
      window.history.replaceState({}, document.title);
    }
  }, [location]);

  useEffect(() => {
    // Only load Python runtime after user leaves landing page
    if (!showStart && !skulptReady) {
      loadSkulpt()
        .then(() => setSkulptReady(true))
        .catch((error) => {
          console.error("Failed to load Skulpt:", error);
          toast({ title: "Python Runtime Error", description: "Gagal load Python runtime. Coba refresh halaman.", variant: "destructive" });
          setSkulptReady(false);
        });
    }
  }, [showStart, skulptReady, toast]);

  const handleSendToChat = (message: string) => {
    chatRef.current?.sendMessage(message);
    if (isMobile) {
      setMobileTab("chat");
    } else if (viewMode === "code") {
      setViewMode("both");
    }
  };

  // Tampilkan hasil AI (Explain/Debug/CheckAnswer) langsung sebagai pesan asisten
  const handleSendAIResult = (
    message: string,
    usage?: { inputTokens: number; outputTokens: number },
    _isPass?: boolean  // unused — view switch dihandle oleh useEffect di bawah
  ) => {
    chatRef.current?.displayAssistantMessage(message, usage);
    // Buka panel chat untuk Explain/Debug/BELUM — LULUS dihandle oleh useEffect
    if (isMobile) {
      setMobileTab("chat");
    } else if (viewMode === "code") {
      setViewMode("both");
    }
  };

  // ── Save code to DB ─────────────────────────────────────────────────────
  const handleSaveCode = async (codeToSave: string): Promise<{ success: boolean }> => {
    const user = authService.getUser();
    if (!user) {
      toast({
        title: "Belum login",
        description: "Login dulu untuk menyimpan kode ke database.",
        variant: "destructive",
      });
      return { success: false };
    }

    // Grab the active conversation ID, or auto-create one if none exists
    const title = `Snippet Kode — ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    let conversationId = await chatRef.current?.getOrCreateConversationId(title);

    const { error } = await backendService.saveCodeSnippet(
      user.id,
      codeToSave,
      "python",
      conversationId || undefined,
      `Manual save — ${new Date().toLocaleTimeString()}`
    );

    if (error) {
      toast({
        title: "Gagal menyimpan",
        description: "Coba lagi atau periksa koneksi internet.",
        variant: "destructive",
      });
      return { success: false };
    }

    toast({
      title: "✅ Kode tersimpan!",
      description: conversationId
        ? "Kode berhasil disimpan ke database, terhubung ke chat aktif."
        : "Kode berhasil disimpan ke database.",
      duration: 2500,
    });
    return { success: true };
  };

  const handleRemoveChallenge = () => {
    try {
      const isJson = code.trim().startsWith("[") && code.trim().endsWith("]");
      if (isJson) {
        const cellList = JSON.parse(code);
        const updated = cellList.map((c: any) => ({
          ...c,
          // Regex: [^\r\n]* agar match Windows (\r\n) dan Unix (\n) line endings
          code: c.code.replace(/# 🎯 TANTANGAN:[^\r\n]*/g, "").trimStart()
        }));
        setCode(JSON.stringify(updated));
      } else {
        setCode(code.replace(/# 🎯 TANTANGAN:[^\r\n]*/g, "").trimStart());
      }
    } catch (e) {
      console.error("Failed to unlock challenge:", e);
    }
  };

  // Hitung lebih awal agar bisa dipakai oleh useEffect di bawah
  const isChallengeActive = code.includes("🎯 TANTANGAN");

  // ── Auto-buka AI Chat ketika challenge selesai (isChallengeActive: true → false) ───
  // Menggunakan useEffect agar tidak ada stale closure issue (tidak perlu setTimeout)
  const prevChallengeRef = useRef(false);
  useEffect(() => {
    const wasActive = prevChallengeRef.current;
    prevChallengeRef.current = isChallengeActive;
    if (wasActive && !isChallengeActive) {
      // Tantangan baru saja selesai — buka panel chat
      if (isMobile) {
        setMobileTab("chat");
      }
      // Desktop: lock screen otomatis hilang saat isChallengeActive false,
      // chat panel sudah terlihat — tidak perlu ubah viewMode
    }
  }, [isChallengeActive, isMobile]);

  // ── Shared nodes for reuse across layouts ─────────────────────────────────
  const editorNode = (
    <NotebookEditor
      ref={notebookRef}
      code={code}
      onChange={setCode}
      onSendToChat={handleSendToChat}
      onSendAIResult={handleSendAIResult}
      onSaveCode={handleSaveCode}
      isRuntimeReady={skulptReady}
    />
  );

  const chatNode = (
    <ChatInterface
      ref={chatRef}
      getCurrentCode={() => code}
      getNotebookContext={() => notebookRef.current?.getCells()}
      onLoadCode={(c) => setCode(c)}
      onSignInClick={() => setShowAuth(true)}
      isChallengeActive={isChallengeActive}
      onRemoveChallenge={handleRemoveChallenge}
    />
  );

  return (
    <div className="h-screen flex flex-col overflow-hidden relative bg-background">
      <Helmet>
        <title>AI Coding Assistant</title>
        <meta name="description" content="UNKLAB AI Code (unklab-aicode) - Interactive Python coding environment with AI chatbot assistance. Write, execute, and improve Python code with instant AI feedback." />
        <meta name="keywords" content="unklab-aicode, unklab ai code, UNKLAB, AI coding assistant, Python IDE, online Python editor, AI programming help, code debugging" />
        <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=0" />
        <link rel="canonical" href="https://unklab-aicode.online/" />
      </Helmet>
      <Particles />

      {/* Landing page overlay */}
      {showStart && (
        <div className="fixed inset-0 z-50 bg-background overflow-y-auto">
          <LandingPage onGetStarted={() => setShowStart(false)} />
        </div>
      )}

      {/* Auth modal */}
      {showAuth && !showStart && (
        <AuthScreen onAuthenticated={() => setShowAuth(false)} />
      )}

      {/* Navbar — hide view-mode toggle on mobile (use bottom nav instead) */}
      <Navbar
        viewMode={isMobile ? undefined : viewMode}
        onViewModeChange={isMobile ? undefined : setViewMode}
        onSignInClick={() => setShowAuth(true)}
      />

      {/* ── MOBILE LAYOUT ──────────────────────────────────────────────────── */}
      {isMobile ? (
