export default Index;

import { API_BASE_URL } from "@/config";
import { getSupabaseClient } from "@/lib/supabaseClient";

export interface User {
  id: string;
  email: string;
  username?: string;
}

// Removed AuthSession since tokens are now entirely handled by backend HttpOnly cookies

// ── Cached user so we don't hit /api/me on every isAuthenticated() check ──────
let cachedUser: User | null = null;

class AuthService {
  // ===== SIGNUP =====
  async signup(email: string, password: string, username?: string): Promise<{ user: User | null; error: Error | null }> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/signup`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, username })
      });

      if (!response.ok) {
        let errorMessage = 'Signup failed';
        try {
          const errorData = await response.json();
          errorMessage = errorData.error || errorData.message || errorMessage;
        } catch (e) {
          errorMessage = await response.text() || errorMessage;
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      if (!data.user) throw new Error('Invalid response from backend');

      const user: User = { id: data.user.id, email: data.user.email, username: data.user.username };
      cachedUser = user;

      return { user, error: null };
    } catch (error) {
      console.error('Signup error:', error);
      return { user: null, error: error as Error };
    }
  }

  // ===== LOGIN =====
  async login(email: string, password: string): Promise<{ user: User | null; error: Error | null }> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/login`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });

      if (!response.ok) {
        let errorMessage = 'Login failed';
        try {
          const errorData = await response.json();
          errorMessage = errorData.error || errorData.message || errorMessage;
        } catch (e) {
          errorMessage = await response.text() || errorMessage;
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      if (!data.user) throw new Error('Invalid response from backend');

      const user: User = { id: data.user.id, email: data.user.email, username: data.user.username };
      cachedUser = user;

      return { user, error: null };
    } catch (error) {
      console.error('Login error:', error);
      return { user: null, error: error as Error };
    }
  }

  // ===== LOGOUT =====
  async logout(): Promise<void> {
    try {
      await fetch(`${API_BASE_URL}/auth/logout`, {
        method: 'POST',
        credentials: 'include'
        // Backend baru langsung baca cookie — tidak perlu kirim Bearer
      });
    } catch (error) {
      console.error('Logout request failed:', error);
    }

    cachedUser = null;
    // Also call clear-session as a belt-and-suspenders cleanup
    try {
      await fetch(`${API_BASE_URL}/auth/clear-session`, {
        method: 'POST',
        credentials: 'include'
      });
    } catch (_) {}
  }

  // ===== VERIFY TOKEN (via /api/me) =====
  async verifyToken(): Promise<{ valid: boolean; user: User | null }> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/me`, {
        method: 'GET',
        credentials: 'include'
      });

      if (!response.ok) {
        // Backend auto-refreshes inside requireAuth.
        // If still failing, session is truly dead.
        cachedUser = null;
        return { valid: false, user: null };
      }

      const data = await response.json();
      const user: User = { id: data.id, email: data.email, username: data.username };
      cachedUser = user;
      return { valid: true, user };
    } catch (error) {
      return { valid: false, user: null };
    }
  }

  // ===== REFRESH TOKEN =====
  // Backend reads refresh_token from cookie — frontend sends NO body
  async refreshToken(): Promise<boolean> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/refresh`, {
        method: 'POST',
        credentials: 'include'
        // No body needed — backend reads refresh_token from HttpOnly cookie
      });

      if (!response.ok) {
        cachedUser = null;
        return false;
      }

      // Backend updated the cookies server-side; re-fetch /api/me to refresh cachedUser
      await this.verifyToken();
      return true;
    } catch (error) {
      cachedUser = null;
      return false;
    }
  }

  // ===== GOOGLE OAUTH =====
  async loginWithGoogle(): Promise<{ error: Error | null }> {
    try {
      window.location.href = `${API_BASE_URL}/auth/google/login`;
      return { error: null };
    } catch (error) {
      console.error('Google OAuth error:', error);
      return { error: error as Error };
    }
  }

  // ===== FORGOT PASSWORD =====
  async forgotPassword(email: string): Promise<{ success: boolean; error: Error | null }> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/forgot-password`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email })
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Failed to send reset email');
      }

      return { success: true, error: null };
    } catch (error) {
      console.error('Forgot password error:', error);
      return { success: false, error: error as Error };
    }
  }

  // ===== RESET PASSWORD =====
  async resetPassword(access_token: string, refresh_token: string, newPassword: string): Promise<{ success: boolean; error: Error | null }> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/reset-password`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ access_token, refresh_token, password: newPassword })
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Failed to reset password');
      }

      return { success: true, error: null };
    } catch (error) {
      console.error('Reset password error:', error);
      return { success: false, error: error as Error };
    }
  }

  // ===== SESSION MANAGEMENT (COOKIE BASED) =====

  // Backend automatically manages cookies, so we don't need a saveSession call.

  // ===== USER & AUTH STATE =====

  // Synchronous check via cache — returns last known user without network call
  getUser(): User | null {
    return cachedUser;
  }

  // Async: hits /api/me to get fresh user data from server  
  async fetchCurrentUser(): Promise<User | null> {
    try {
      const response = await fetch(`${API_BASE_URL}/auth/me`, {
        method: 'GET',
        credentials: 'include'
      });
      if (!response.ok) {
        cachedUser = null;
        return null;
      }
      const data = await response.json();
      cachedUser = { id: data.id, email: data.email, username: data.username };
      return cachedUser;
    } catch {
      return null;
    }
  }

  // Warm up the cache on app startup — call this once in App.tsx or Index.tsx
  async initSession(): Promise<User | null> {
    return this.fetchCurrentUser();
  }

  isAuthenticated(): boolean {
    // Relies on cachedUser. Call initSession() on app boot to warm it up.
    return !!cachedUser;
  }

  // Access token is HttpOnly — not readable by JS. Return empty for Bearer compat.
  // credentials: 'include' in fetch calls handles sending the cookie automatically.
  getAccessToken(): string | null {
    return null; // Intentionally null — token is in HttpOnly cookie, inaccessible to JS
  }

  getAuthHeaders(): Record<string, string> {
    // credentials: 'include' handles cookie attachment automatically
    // Return empty object since all auth goes via cookie now
    return {};
  }
}

export const authService = new AuthService();

// Deklarasi global untuk TypeScript
declare global {
  interface Window {
    // Skulpt mengekspor objek utama sebagai `Sk`
    Sk: any;
  }
}

// Fungsi untuk memuat Skulpt secara dinamis dari CDN
export const loadSkulpt = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    if (window.Sk) {
      console.log("Skulpt already loaded");
      resolve();
      return;
    }

    console.log("Loading Skulpt...");

    const CORE_SRCS = [
      "https://cdn.jsdelivr.net/npm/skulpt@1.2.0/dist/skulpt.min.js",
      "https://unpkg.com/skulpt@1.2.0/dist/skulpt.min.js",
      "/skulpt.min.js",
    ];
    const STDLIB_SRCS = [
      "https://cdn.jsdelivr.net/npm/skulpt@1.2.0/dist/skulpt-stdlib.js",
      "https://unpkg.com/skulpt@1.2.0/dist/skulpt-stdlib.js",
      "/skulpt-stdlib.js",
    ];

    const TIMEOUT_MS = 15000;
    let settled = false;
    const finish = (ok: boolean, err?: any) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      ok
        ? resolve()
        : reject(err || new Error("Failed to load Skulpt retrying"));
    };
    const timer = window.setTimeout(() => {
      console.error("Timed out loading Skulpt");
      finish(false, new Error("Timed out loading Skulpt"));
    }, TIMEOUT_MS);

    const tryLoad = (urls: string[], onLoaded: () => void) => {
      let i = 0;
      const next = () => {
        if (i >= urls.length) {
          onLoaded();
          return;
        }
        const url = urls[i++];
        const s = document.createElement("script");
        s.async = true;
        s.src = url;
        s.crossOrigin = "anonymous";
        s.onload = () => {
          s.remove();
          onLoaded();
        };
        s.onerror = () => {
          console.warn("Failed loading", url, "— trying next");
          s.remove();
          next();
        };
        document.head.appendChild(s);
      };
      next();
    };

    // Load core → then stdlib
    tryLoad(CORE_SRCS, () => {
      if (!window.Sk) {
        // If core not attached after trying all URLs
        finish(false, new Error("Skulpt core not available"));
        return;
      }
      console.log("Skulpt core loaded");
      tryLoad(STDLIB_SRCS, () => {
        if (!window.Sk || !window.Sk.builtinFiles) {
          finish(false, new Error("Skulpt stdlib not available"));
          return;
        }
        console.log("Skulpt stdlib loaded");
        finish(true);
      });
    });
  });
};

// Fungsi untuk menjalankan kode Python di browser
export const runPythonCode = async (
  code: string,
  opts?: {
    inputProvider?: (prompt?: string) => Promise<string>;
    onStdout?: (text: string) => void;
    onStderr?: (text: string) => void;
    signal?: AbortSignal;
  }
): Promise<string[]> => {
  return new Promise((resolve) => {
    if (!window.Sk) {
      resolve(["Error: Skulpt is not loaded. Please refresh the page."]);
      return;
    }

    const output: string[] = [];

    // Konfigurasi Skulpt
    window.Sk.configure({
      output: (text: string) => {
        output.push(text);
        if (opts?.onStdout) opts.onStdout(text);
      },
      read: (filename: string) => {
        if (
          window.Sk.builtinFiles === undefined ||
          window.Sk.builtinFiles["files"][filename] === undefined
        ) {
          throw new Error(`File not found: ${filename}`);
        }
        return window.Sk.builtinFiles["files"][filename];
      },
      // batas waktu eksekusi (opsional)
      inputfun: async (prompt?: string) => {
        if (opts?.inputProvider) {
          try {
            const val = await opts.inputProvider(prompt);
            return val;
          } catch (e) {
            throw e;
          }
        }
        // Fallback ke prompt browser jika tidak ada provider
        const val = window.prompt(prompt || "Input:") || "";
        return val;
      },
      inputfunTakesPrompt: true,
    });

    // Timeout execution config:
    // Setup yield limit to prevent UI freezing (yields every 100ms)
    window.Sk.yieldLimit = 100;
    
    // Normal execLimit is 5 minutes. If aborted, we set it to 1ms to instantly trigger a TimeLimitError.
    window.Sk.execLimit = 5 * 60 * 1000; 

    const onAbort = () => {
      window.Sk.execLimit = 1; 
    };

    if (opts?.signal) {
      opts.signal.addEventListener("abort", onAbort);
    }

    // Jalankan kode Python secara asynchronous
    window.Sk.misceval
      .asyncToPromise(() =>
        window.Sk.importMainWithBody("<stdin>", false, code, true)
      )
      .then(() => {
        resolve(output);
      })
      .catch((err: any) => {
        const errStr = err.toString();
        // Cek jika error karena dihentikan secara sengaja (TimeLimitError akibat execLimit = 1)
        const isAborted = opts?.signal?.aborted && errStr.includes("TimeLimitError");
        const msg = isAborted ? "KeyboardInterrupt: Execution stopped by user." : `Error: ${errStr}`;
        if (opts?.onStderr) opts.onStderr(msg);
        resolve([msg]);
      })
      .finally(() => {
        if (opts?.signal) {
          opts.signal.removeEventListener("abort", onAbort);
        }
      });
  });
};

